code='''def transform(grid):
    border = grid[0][0]
    h, w = len(grid), len(grid[0])
    out = [[0 if v == border else v for v in row] for row in grid]
    green_rows = [r for r in range(h) if sum(v == 3 for v in grid[r]) > w // 2]
    if green_rows:
        for r in green_rows:
            out[r] = [3] * w
        red_rows = [r for r in range(h) if 2 in grid[r]]
        red_cols = sorted({c for r in red_rows for c in range(w) if grid[r][c] == 2})
        first = red_cols[0]
        period = next(c - first for c in red_cols if c > first)
        width = 0
        while first + width in red_cols:
            width += 1
        for r in range(h):
            if r not in green_rows:
                for c in range(w):
                    phase = (c - first) % period
                    if c >= first and phase < width:
                        out[r][c] = 2 if r in red_rows else border
    else:
        rows = {r for r in range(h) for c in range(w) if grid[r][c] == 2}
        for r in rows:
            for c in range(w):
                if out[r][c] == 0:
                    out[r][c] = border
    return out
